function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // clouds
  ctx.fillStyle = 'white';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(100 + i*100 + 50*Math.cos(t+i), 100 + 20*Math.sin(t+i), 20 + 10*Math.sin(t+i), 0, 2*Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // trees
  ctx.lineWidth = 3;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(200 + i*150, H-50);
    ctx.lineTo(200 + i*150, H-150-50*Math.sin(t+i));
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(200 + i*150, H-150-50*Math.sin(t+i), 20, 0, 2*Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  ctx.restore();
}
